import {HEROES,ITEMS,SKILLS,LINKS,BUILDINGS} from './data.js';
import {stats,itemName,itemStats,nextXp,saveMeta,upgradeCost,buildingCost,settlementInfo} from './state.js';
import {REGIONS,TOWNS,INTERIORS,OBJECTS,WORLD_W,WORLD_H,regionAt} from './world.js';
import {battleView} from './battle.js';
import {drawHero,drawPortrait,drawItemIcon} from './art.js';
import {drawMinimap} from './render.js';

export const TABS=['Map','Party','Inventory','Skills','Quests','Save','Settings'];
const SLOTS=['weapon','armor','accessory'];
const STAT_NAMES={maxHp:'Max HP',maxMp:'Max MP',atk:'Attack',mag:'Magic',def:'Defense',spd:'Speed',crit:'Critical'};
const ICONS={clock:'M7 3h10M7 21h10M8 3c0 6 8 12 8 18M16 3c0 6-8 12-8 18',coins:'M19 7c0 2-3 4-7 4S5 9 5 7s3-4 7-4 7 2 7 4ZM5 7v5c0 2 3 4 7 4s7-2 7-4V7M5 12v5c0 2 3 4 7 4s7-2 7-4v-5',ore:'m4 8 6-5 8 2 4 10-9 6-10-5 1-8Zm0 0 8 4 6-7M12 12l1 9M12 12l10 3',food:'M12 22V4M12 10C5 10 4 5 5 2c6 0 7 4 7 8Zm0 6c7 0 8-5 7-8-6 0-7 4-7 8ZM12 20c-6 0-8-4-7-7 5 0 7 3 7 7',energy:'m13 2-9 12h7l-1 8 10-13h-7l0-7Z',renown:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16M15 5v16',party:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-3c0-3 3-5 7-5s7 2 7 5v3M17 4a4 4 0 0 1 0 7M19 14c2 1 3 2 3 4v3',inventory:'M5 8h14l2 13H3L5 8ZM8 8V5a4 4 0 0 1 8 0v3M3 13h18M10 12v4h4v-4',skills:'M12 3v6M12 15v6M3 12h6M15 12h6m-9-6 6 6-6 6-6-6 6-6Z',quests:'M5 3h14v18H5V3ZM8 7h8M8 11h8M8 15h5',save:'M4 3h13l3 3v15H4V3Zm4 0v7h8V3M8 21v-7h8v7',settings:'M3 6h18M3 12h18M3 18h18M8 3v6M16 9v6M10 15v6',weapon:'m5 19 2-2M3 15l6 6M6 18 19 5l1-3-3 1L4 16',armor:'m8 3 4 2 4-2 6 5-4 5-2-2v10H8V11l-2 2-4-5 6-5Z',accessory:'M7 9a5 5 0 0 1 10 0M5 14l7-7 7 7-7 7-7-7ZM8 14l4-4 4 4-4 4-4-4Z',consumable:'M9 3h6M10 3v5l-5 8c-2 3 1 5 3 5h8c2 0 5-2 3-5l-5-8V3M7 14h10',farm:'M3 20h18M5 20v-8M12 20V6M19 20v-8M12 10C6 9 7 3 7 3s6 1 5 7Zm0 4c7-1 6-7 6-7s-6 1-6 7M3 7l2 3 3-3M16 7l3 3 3-3',mine:'m4 4 16 16M4 11C7 3 13 1 21 5M6 9l3-3M3 21l5-7 5 7H3Z',extractor:'M8 3h8v4H8V3ZM6 7h12l3 14H3L6 7Zm7 3-5 6h4l-1 4 5-7h-4l1-3Z',forge:'M3 11h18l-4 5h-4v5H8v-5l-5-5ZM9 3v4M14 2v5M18 4v3',barracks:'M3 11 12 3l9 8M5 9v12h14V9M10 21v-7h4v7M8 11h2M14 11h2',archive:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3V4ZM12 6v15M6 8h3M15 8h3M6 12h3M15 12h3',walls:'M3 3h4v4h3V3h4v4h3V3h4v18H3V3ZM3 13h18M8 13v8M16 13v8M12 7v6',hall:'M2 10 12 2l10 8H2ZM4 10v10M9 10v10M15 10v10M20 10v10M2 22h20',attack:'m5 19 2-2M3 15l6 6M6 18 19 5l1-3-3 1L4 16',tech:'M12 2 9 9l-7 3 7 3 3 7 3-7 7-3-7-3-3-7Z',defend:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z',item:'M9 3h6M10 3v5l-5 8c-2 3 1 5 3 5h8c2 0 5-2 3-5l-5-8V3M7 14h10',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',wait:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 6v6l4 2',close:'m6 6 12 12M18 6 6 18',arrow:'M4 12h16m-6-6 6 6-6 6'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.renown}"/></svg>`;
const num=n=>Math.floor(Number(n)||0).toLocaleString();
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const percent=(n,m)=>clamp((n||0)/(m||1)*100,0,100);
const values=o=>Object.values(o);
function button(label,action,payload={},options={}){return `<button type="button" class="${options.class||'button'}" data-action="${esc(action)}" data-payload="${esc(JSON.stringify(payload))}"${options.disabled?' disabled':''}${options.label?` aria-label="${esc(options.label)}"`:''}${options.title?` title="${esc(options.title)}"`:''}>${label}</button>`;}
const itemIcon=(id,size=28)=>`<canvas data-item-icon="${esc(id)}" data-sprite-width="${size*2}" data-sprite-height="${size*2}" style="width:${size}px;height:${size}px" aria-label="${esc(ITEMS[id]?.name||id)} artwork"></canvas>`;
const price=cost=>`<span class="price">${Object.entries(cost||{}).filter(([,v])=>v>0).map(([key,v])=>`<span>${icon(key)}${num(v)} <span class="sr-only">${key}</span></span>`).join('')}</span>`;
const costWords=cost=>Object.entries(cost||{}).filter(([,v])=>v>0).map(([k,v])=>`${v} ${k}`).join(' · ');
const affordable=(s,cost)=>!!cost&&Object.entries(cost).every(([k,v])=>(s.resources[k]||0)>=v);
const owner=(s,uid)=>s.heroes.find(h=>values(h.equip).includes(uid));
const getItem=(s,uid)=>s.inventory.find(i=>i.uid===uid);
const heroStyle=id=>`--hero:${HEROES[id]?.color||'#e0b879'}`;
const portrait=(id,w=70,h=96)=>`<canvas class="portrait" data-portrait="${esc(id)}" data-sprite-width="${w*2}" data-sprite-height="${h*2}" style="width:${w}px;height:${h}px" aria-label="${esc(HEROES[id]?.name||(id==='iona'?'Iona':id))} portrait"></canvas>`;
const meter=(value,max,color)=>`<div class="meter"${color?` style="--meter:${color}"`:''}><i style="width:${percent(value,max)}%"></i></div>`;
const statText=st=>Object.entries(st).map(([k,v])=>`+${v} ${STAT_NAMES[k]||k}`).join(' · ');
const equippedName=(s,h,slot)=>h.equip[slot]?itemName(getItem(s,h.equip[slot])):'Empty';
let activeGame=null,bound=false,lastHud='',lastOverlay='';

// Reconcile nodes in place: a filling ATB gauge never replaces the button under a finger.
function reconcile(parent,html){const template=document.createElement('template');template.innerHTML=html;patchChildren(parent,template.content);}
function patchChildren(old,newNode){let index=0;while(index<newNode.childNodes.length){const fresh=newNode.childNodes[index],current=old.childNodes[index];if(!current){old.appendChild(fresh.cloneNode(true));index++;continue;}if(current.nodeType!==fresh.nodeType||current.nodeName!==fresh.nodeName){old.replaceChild(fresh.cloneNode(true),current);index++;continue;}if(current.nodeType===3){if(current.nodeValue!==fresh.nodeValue)current.nodeValue=fresh.nodeValue;}else if(current.nodeType===1){const runtimeSize=current.tagName==='CANVAS'&&fresh.hasAttribute('data-sprite-width'),keepSize=name=>runtimeSize&&(name==='width'||name==='height');for(const a of [...current.attributes])if(!fresh.hasAttribute(a.name)&&!keepSize(a.name))current.removeAttribute(a.name);for(const a of [...fresh.attributes])if(current.getAttribute(a.name)!==a.value&&!keepSize(a.name))current.setAttribute(a.name,a.value);patchChildren(current,fresh);if(current.tagName==='SELECT')current.value=fresh.querySelector('option[selected]')?.value||fresh.value;}index++;}while(old.childNodes.length>newNode.childNodes.length)old.lastChild.remove();}
function setup(g){activeGame=g;g.ui??={tab:0,hero:0};g.ui.tab??=0;g.ui.hero??=0;if(bound)return;bound=true;const stage=document.getElementById('game');const resize=()=>stage.style.setProperty('--ui-scale',stage.clientWidth/960);new ResizeObserver(resize).observe(stage);resize();stage.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;event.stopPropagation();const payload=JSON.parse(b.dataset.payload||'{}');dispatch(activeGame,b.dataset.action,payload);});stage.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting)activeGame.act('setting',{key:el.dataset.setting,value:Number(el.value)});});stage.addEventListener('wheel',event=>{if(!event.target.closest('.atlas'))return;event.preventDefault();mapChange(activeGame,{zoom:(activeGame.ui.map?.zoom||1)*(event.deltaY<0?1.13:1/1.13)});},{passive:false});let drag=null;stage.addEventListener('pointerdown',e=>{if(!e.target.closest('.atlas')||e.target.closest('button')||e.target.closest('.travel'))return;const m=mapState(activeGame);drag={x:e.clientX,y:e.clientY,cx:m.cx,cy:m.cy,zoom:m.zoom};stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointermove',e=>{if(!drag)return;const atlas=stage.querySelector('.atlas');const scale=atlas?.getBoundingClientRect().width||550;const worldPerPx=WORLD_W/(scale*drag.zoom);mapChange(activeGame,{cx:drag.cx-(e.clientX-drag.x)*worldPerPx,cy:drag.cy-(e.clientY-drag.y)*worldPerPx});});stage.addEventListener('pointerup',()=>drag=null);stage.addEventListener('pointercancel',()=>drag=null);}
function dispatch(g,action,payload){if(action==='uiTab'){g.ui.tab=payload.tab;g.refresh();return;}if(action==='uiHero'){g.ui.hero=payload.hero;g.refresh();return;}if(action==='uiItem'){g.ui.item=payload.uid;g.refresh();return;}if(action==='uiFilter'){g.ui.filter=payload.filter;g.ui.item=null;g.refresh();return;}if(action==='uiSlot'){g.ui.slot=payload.slot;const h=g.s.heroes[g.ui.hero];if(h.equip[payload.slot])g.ui.item=h.equip[payload.slot];g.refresh();return;}if(action==='uiShop'){g.ui.shopTab=payload.tab;g.refresh();return;}if(action==='uiPlot'){g.settlementPlot=payload.plot;g.refresh();return;}if(action==='uiMap'){const m=mapState(g);if(payload.reset)g.ui.map={zoom:1,cx:WORLD_W/2,cy:WORLD_H/2};else mapChange(g,{zoom:m.zoom*payload.factor});g.refresh();return;}if(action==='uiDelete'){g.ui.deleteSlot=payload.slot;g.refresh();return;}if(action==='deleteSave')g.ui.deleteSlot=null;g.act(action,payload);}
function mapState(g){return g.ui.map??={zoom:1,cx:WORLD_W/2,cy:WORLD_H/2};}
function mapChange(g,change){const m=mapState(g);Object.assign(m,change);m.zoom=clamp(m.zoom,.6,2.8);m.cx=clamp(m.cx,0,WORLD_W);m.cy=clamp(m.cy,0,WORLD_H);g.refresh();}
function heroTabs(g){return `<div class="hero-tabs">${g.s.heroes.map((h,i)=>button(`<i class="hero-dot"></i>${esc(h.name)}`,'uiHero',{hero:i},{class:`hero-tab ${g.ui.hero===i?'active':''}`,label:`Select ${h.name}`} ).replace('class="hero-tab',`style="${heroStyle(h.id)}" class="hero-tab`)).join('')}</div>`;}
function title(g){const meta=saveMeta('auto');return `<section class="title-screen" aria-label="Title screen"><div class="title-content"><div class="eyebrow">An adventure beyond the last hour</div><div class="title-rule"></div><h1>Chronoforge</h1><div class="title-subtitle">The Unwritten Hour</div><p class="title-blurb">Three unlikely companions. A world learning to live again. And somewhere beyond the broken clocks, a voice calling you home.</p><div class="title-actions">${meta?button(`Continue your story ${icon('arrow')}`,'continue',{slot:'auto'},{class:'button primary'}):''}${button(`${meta?'Begin a new journey':'Begin your journey'} ${icon('arrow')}`,'newGame',{}, {class:`button ${meta?'':'primary'}`,label:'New game'})}</div></div><div class="title-sigil"><svg viewBox="0 0 180 180" aria-hidden="true"><circle cx="90" cy="90" r="79"/><circle cx="90" cy="90" r="72" stroke-dasharray="1 8"/><path d="M59 41h62M59 139h62M64 42c0 40 52 57 52 97M116 42c0 40-52 57-52 97M90 8v18M90 154v18M8 90h18M154 90h18M34 34l13 13M133 133l13 13M146 34l-13 13M47 133l-13 13"/><path d="m90 75 15 15-15 15-15-15Z" fill="currentColor" opacity=".5"/></svg></div><div class="title-foot"><span>Move · Explore · Build · Remember</span><span>WASD / Arrows to move &nbsp; · &nbsp; Space to interact</span></div></section>`;}
function ribbon(g){return `<header class="resource-ribbon"><div class="ribbon-brand">${icon('clock')}<span>CHRONOFORGE</span></div>${['coins','ore','food','energy','renown'].map(k=>`<div class="resource" title="${k}">${icon(k)}<b>${num(g.s.resources[k])}</b><small>${k}</small></div>`).join('')}${button('Journal <kbd>Tab</kbd>','menu',{tab:g.ui.tab},{class:'ribbon-menu',label:'Open journal'})}</header>`;}
function worldHud(g){const r=g.s.party.interior?REGIONS.find(r=>r.id===INTERIORS[g.s.party.interior]?.town):regionAt(g.s.party.x,g.s.party.y);const room=INTERIORS[g.s.party.interior];const near=g.nearby||g.nearest||g.interactTarget;const target=typeof near==='object'?near:null;return `${ribbon(g)}<div class="location-plate"><div class="eyebrow">${room?'A moment under shelter':esc(r?.subtitle||'The open road')}</div><h2>${esc(room?.name||r?.name||'The Unwritten World')}</h2></div><div class="objective-plate"><div class="eyebrow">The thread ahead</div>${esc(g.storyObjective||'Find your bearings in Haventide.')}</div><div class="mini-party">${g.s.heroes.map(h=>`<div class="mini-hero" style="${heroStyle(h.id)}"><div class="hero-name"><span>${esc(h.name)}</span><small>Lv ${h.level}</small></div>${meter(h.hp,stats(g.s,h).maxHp)}</div>`).join('')}</div><div class="minimap-shell"><canvas id="minimap" width="278" height="154" aria-label="Local minimap"></canvas><div class="minimap-caption">${room?'Haventide & the old roads':esc(r?.name||'The continent')} · Map [1]</div></div>${target?button(`<kbd>Space</kbd> ${esc(target.name)}`,'interact',{id:target.id},{class:'interact-hint'}):''}<footer class="bottom-rail"><span><kbd>WASD</kbd> / <kbd>↑↓←→</kbd> Move</span><span><kbd>Shift</kbd> Run</span><span><kbd>C</kbd> / <kbd>Space</kbd> Interact</span><span><kbd>Click</kbd> Walk</span><span><kbd>Tab</kbd> Journal</span><span class="rail-right">${g.s.settlement.plots.filter(Boolean).length} / 7 commons plots restored</span></footer>`;}
function menu(g){const bodies=[mapTab,partyTab,inventoryTab,skillsTab,questsTab,saveTab,settingsTab];return `<div class="scrim"></div><section class="menu-frame" role="dialog" aria-label="Travel journal"><div class="menu-title">${icon('clock')}<span class="eyebrow">The travel journal</span><span class="chapter">${esc(g.s.flags.truth?'Toward the Unwritten Hour':'A world worth mending')}</span>${button('×','close',{}, {class:'icon-button',label:'Close journal'})}</div><nav class="menu-tabs" aria-label="Journal tabs">${TABS.map((name,i)=>button(`${icon(name.toLowerCase())}${name}<span class="tab-number">${i+1}</span>`,'uiTab',{tab:i},{class:`tab ${g.ui.tab===i?'active':''}`,label:name})).join('')}</nav><div class="menu-body" role="tabpanel" aria-label="${TABS[g.ui.tab]} panel">${(bodies[g.ui.tab]||mapTab)(g)}</div><footer class="menu-footer"><span><kbd>Q</kbd> <kbd>E</kbd> / <kbd>←</kbd> <kbd>→</kbd> Tabs &nbsp; <kbd>1–7</kbd> Jump &nbsp; <kbd>Esc</kbd> Close</span><span>${g.ui.tab===0?'Drag / WASD to pan · wheel / + − to zoom · R to reset':g.ui.tab===2?'W / S select gear · A / D select hero · Enter equip · X remove':'Every hour is still ours.'}</span></footer></section>`;}
function partyTab(g){return `<div class="party-grid">${g.s.heroes.map(h=>{const t=stats(g.s,h);return `<article class="party-card" style="${heroStyle(h.id)}"><div class="party-heading"><h3>${esc(h.name)}</h3><span class="level">LV ${h.level}</span></div><div class="party-role">${esc(HEROES[h.id].role)}</div><div class="portrait-stage">${portrait(h.id,75,105)}</div><div class="meter-label"><span>HP</span><b>${h.hp} / ${t.maxHp}</b></div>${meter(h.hp,t.maxHp)}<div class="meter-label"><span>MP</span><b>${h.mp} / ${t.maxMp}</b></div>${meter(h.mp,t.maxMp,'#88bfc9')}<div class="xp-line"><span>${h.xp} / ${nextXp(h.level)} XP</span><b>${h.sp} skill points</b></div>${meter(h.xp,nextXp(h.level),'#c5a361')}<div class="stat-grid">${['atk','mag','def','spd','crit'].map(k=>`<div class="stat-cell"><span>${STAT_NAMES[k]}</span><b>${t[k]}${k==='crit'?'%':''}</b></div>`).join('')}</div>${SLOTS.map(slot=>`<div class="equipment-line"><span>${slot}</span>${esc(equippedName(g.s,h,slot))}</div>`).join('')}</article>`;}).join('')}</div>`;}
function inventoryItems(g){return g.s.inventory.filter(i=>!g.ui.filter||g.ui.filter==='all'||ITEMS[i.id].slot===g.ui.filter);}
function inventoryTab(g){const s=g.s,h=s.heroes[g.ui.hero]||s.heroes[0],items=inventoryItems(g);let selected=items.find(i=>i.uid===g.ui.item)||items[0];const d=ITEMS[selected?.id],own=selected&&owner(s,selected.uid),st=stats(s,h),current=d&&SLOTS.includes(d.slot)?getItem(s,h.equip[d.slot]):null;const prev=itemStats(current),next=itemStats(selected);const compatible=d&&(!d.heroes||d.heroes.includes(h.id))&&h.level>=d.level&&(!own||own.id===h.id);return `<div class="section-heading"><h2>The party’s pack</h2><span class="muted">${s.inventory.length} items · ${num(s.resources.coins)} coins</span></div><div class="inventory-layout"><div class="inventory-list scroll"><div class="filter-bar">${[['all','All'],['weapon','Weapons'],['armor','Armor'],['accessory','Charms'],['consumable','Supplies']].map(([id,label])=>button(label,'uiFilter',{filter:id},{class:`filter ${(g.ui.filter||'all')===id?'active':''}`})).join('')}</div>${items.map(i=>{const def=ITEMS[i.id],o=owner(s,i.uid);return button(`<span class="item-symbol">${itemIcon(def.id)}</span><span class="item-copy"><strong>${esc(itemName(i))}</strong><small>${esc(def.slot==='consumable'?def.desc:statText(itemStats(i)))}</small></span><span class="item-tag">${o?esc(o.name):`Lv ${def.level}`}</span>`,'uiItem',{uid:i.uid},{class:`item-row ${selected?.uid===i.uid?'active':''}`,label:`Select ${itemName(i)} ${i.uid}`});}).join('')||'<p class="empty">Your pack has room for new discoveries.</p>'}</div><div class="item-details">${heroTabs(g)}<div class="slot-strip">${SLOTS.map(slot=>button(`${slot}<span>${esc(equippedName(s,h,slot))}</span>`,'uiSlot',{slot},{class:`slot-button ${(g.ui.slot||d?.slot)===slot?'active':''}`,label:`Select ${h.name} ${slot} slot`})).join('')}</div>${selected?`<div class="chip">${esc(d.slot)} · ${d.heroes?d.heroes.map(id=>HEROES[id].name).join(' / '):'All companions'} · Level ${d.level}</div><h3>${esc(itemName(selected))}</h3><p class="item-description">${esc(d.desc)}</p>${d.slot!=='consumable'?`<table class="comparison"><thead><tr><th>${esc(h.name)}’s stats</th><th>Now</th><th>Equipped</th><th>Change</th></tr></thead><tbody>${Object.keys(STAT_NAMES).filter(k=>(next[k]||prev[k])).map(k=>{const diff=(next[k]||0)-(prev[k]||0);return `<tr><td>${STAT_NAMES[k]}</td><td>${st[k]}</td><td>${st[k]+diff}</td><td class="${diff>0?'positive':diff<0?'negative':'muted'}">${diff>0?'+':''}${diff}</td></tr>`;}).join('')}</tbody></table>`:`<p class="small muted">${esc(h.name)} · ${h.hp} / ${st.maxHp} HP · ${h.mp} / ${st.maxMp} MP</p>`}<div class="detail-actions"><div class="actions">${d.slot==='consumable'?button(`Use on ${esc(h.name)}`,'useItem',{heroId:h.id,uid:selected.uid},{class:'button primary'}):button(own?.id===h.id?'Equipped':`Equip to ${esc(h.name)}`,'equip',{heroId:h.id,uid:selected.uid},{class:'button primary',disabled:!compatible||own?.id===h.id})}${own?.id===h.id?button('Unequip','unequip',{heroId:h.id,slot:d.slot}):button(`Sell · ${Math.max(1,Math.floor(d.price*(.45+.12*selected.rank)))} coins`,'sell',{uid:selected.uid},{disabled:!!own})}</div><p class="tiny muted" style="margin-top:9px">${own?`Carried by ${esc(own.name)}.`:!compatible&&d.slot!=='consumable'?`Requires ${d.heroes?.map(id=>HEROES[id].name).join(' / ')||'any hero'} at level ${d.level}.`:'Smiths can improve equipment up to rank +3.'}</p></div>`:'<div class="empty">Select an item to compare it with your equipment.</div>'}</div></div>`;}
function skillsTab(g){const s=g.s,h=s.heroes[g.ui.hero]||s.heroes[0];return `<div class="section-heading">${heroTabs(g)}<span class="muted"><span class="gold">${h.sp} skill points</span> · Level ${h.level}</span></div><div class="skill-layout"><div class="skill-list scroll" style="${heroStyle(h.id)}">${values(SKILLS).filter(k=>k.hero===h.id).map(k=>{const learned=h.skills.includes(k.id),blocked=h.level<k.level||(k.requires&&!h.skills.includes(k.requires))||h.sp<k.cost;const req=h.level<k.level?`Reach level ${k.level}`:k.requires&&!h.skills.includes(k.requires)?`Requires ${SKILLS[k.requires].name}`:`${k.cost} SP · Level ${k.level}`;return `<article class="skill-card ${learned?'learned':''}"><div class="skill-node"><span>${learned?'✓':'✦'}</span></div><div class="skill-content"><h4>${esc(k.name)}</h4><p>${esc(k.desc)}</p><div class="skill-meta"><span>${k.mp} MP · ${learned?'Learned':esc(req)}</span>${button(learned?'Learned':`Learn · ${k.cost} SP`,'learn',{heroId:h.id,skillId:k.id},{class:'button small-btn',disabled:learned||blocked,label:`Learn ${k.name}`})}</div></div></article>`;}).join('')}</div><div class="bond-panel scroll"><div class="eyebrow">Coordinated techniques</div><p class="lead" style="margin-top:9px">“Some things can only be carried together.”</p>${values(LINKS).map(l=>`<div class="bond-row ${s.flags[l.flag]?'':'locked'}"><div class="bond-faces">${l.heroes.map(id=>`<i class="hero-dot" style="${heroStyle(id)}"></i>`).join('')}</div><h4>${esc(l.name)} <small class="tiny gold">${s.flags[l.flag]?'UNLOCKED':'LOCKED'}</small></h4><p>${esc(l.desc)}</p><div class="bond-cost">${l.mp} MP each · all partners’ ATB full${s.flags[l.flag]?'':` · ${l.flag==='truth'?'Find Iona’s truth':`Restore the ${l.flag.split('_')[1]} anchor`}`}</div></div>`).join('')}</div></div>`;}
function questsTab(g){const entries=typeof g.journalEntries==='function'?g.journalEntries():[];const anchors=['mire','ember','frost'];return `<div class="quest-layout"><article class="quest-current"><div class="eyebrow">Our shared purpose</div><h3>${esc(g.storyObjective||'Follow the anchor trail')}</h3><p>Kaida’s sister Iona vanished when the clocks broke. The memories held in three anchors are the only trail she left behind.</p><div class="divider"></div>${anchors.map(a=>`<p style="font-size:11px;margin:7px 0;color:${g.s.flags[`anchor_${a}`]?'var(--gold)':'var(--muted)'}">${g.s.flags[`anchor_${a}`]?'◆':'◇'} &nbsp; ${a[0].toUpperCase()+a.slice(1)} memory ${g.s.flags[`anchor_${a}`]?'restored':'awaits'}</p>`).join('')}<div class="divider"></div><p style="font-size:10px">Haventide is part of the journey. Build farms, shelter and places to learn in its seven commons plots. What you rebuild will be waiting when you return.</p></article><div class="quest-list scroll"><div class="eyebrow">Pages from the road</div>${entries.map((e,i)=>typeof e==='string'?`<article class="journal-entry"><h4>Memory ${String(i+1).padStart(2,'0')}</h4><p>${esc(e)}</p></article>`:`<article class="journal-entry"><h4>${esc(e.title||e.name||'A moment remembered')}</h4><p>${esc(e.text||e.body||e.description)}</p></article>`).join('')||`<article class="journal-entry"><h4>The evacuation ferry</h4><p>Kaida held the gangway. Vex carried a broken clock. Rune chose to disobey an order. That was how three strangers became a party.</p></article>`}</div></div>`;}
function saveTab(g){return `<div class="section-heading"><h2>Keep this hour</h2><span class="muted">Three manual saves · independent autosave</span></div><p class="small muted">Your companions, discoveries and commons are saved together.</p><div class="save-list">${['auto','1','2','3'].map(slot=>{const m=saveMeta(slot);return `<div class="save-row"><div class="save-number">${slot==='auto'?'◷':slot.padStart(2,'0')}</div><div class="save-info"><h4>${slot==='auto'?'Autosave':`Memory slot ${slot}`}${m?` · ${esc(m.chapter)}`:''}</h4><p>${m?`Level ${m.level} · ${Math.floor(m.elapsed/60)} minutes · ${m.anchors}/3 anchors · ${new Date(m.savedAt).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}`:'An unwritten page'}</p></div><div class="actions">${slot!=='auto'?button('Save','save',{slot},{label:`Save slot ${slot}`}):''}${button('Load','load',{slot},{disabled:!m,label:`Load ${slot==='auto'?'autosave':`slot ${slot}`}`})}${slot!=='auto'&&m?g.ui.deleteSlot===slot?button('Confirm delete','deleteSave',{slot},{class:'button danger',label:`Confirm delete slot ${slot}`}):button('Delete','uiDelete',{slot},{class:'button subtle',label:`Delete slot ${slot}`}):''}</div></div>`;}).join('')}</div>`;}
function settingsTab(g){const s=g.s.settings;return `<div class="settings-layout"><div><div class="section-heading"><h2>Make yourself at home</h2></div>${[['wait','Wait mode','Time pauses while you choose a command. Use Wait for allies to prepare coordinated techniques.'],['sound','Music & sound','An original score, village ambience and battle cues.'],['reducedMotion','Reduced motion','Calmer flashes, screen effects and interface transitions.']].map(([key,label,desc])=>`<div class="setting-row"><div class="setting-copy"><strong>${label}</strong><p>${desc}</p></div>${button(s[key]?'On':'Off','setting',{key,value:!s[key]},{class:`setting-toggle ${s[key]?'on':''}`,label:`${label}: ${s[key]?'on':'off'}`})}</div>`).join('')}<div class="setting-row"><div class="setting-copy"><strong>Battle speed</strong><p>Choose the pace of active time.</p></div><select class="setting-select" data-setting="speed" aria-label="Battle speed">${[[.75,'Gentle'],[1,'Standard'],[1.5,'Swift'],[2,'Brisk']].map(([n,label])=>`<option value="${n}" ${s.speed===n?'selected':''}>${label}</option>`).join('')}</select></div></div><aside class="controls-guide"><h3>The little things</h3>${[['Move','WASD / ↑↓←→'],['Run','Shift'],['Interact / advance','C / Space / Enter'],['Walk to a point','Click the world'],['Open / close journal','Tab / Esc'],['Previous / next tab','Q / E or ← / →'],['Jump to a tab','1–7'],['Map pan / zoom','WASD / wheel'],['Map reset','R'],['Gear / hero selection','W S / A D']].map(([label,key])=>`<div class="control-line"><span>${label}</span><kbd>${key}</kbd></div>`).join('')}<p class="credits">Chronoforge · The Unwritten Hour<br>Original art, music, characters and places for this remade adventure.</p></aside></div>`;}
function mapTab(g){const m=mapState(g),vw=WORLD_W/m.zoom,vh=vw*.62,x=m.cx-vw/2,y=m.cy-vh/2;const p=g.s.party.interior?g.s.party.returnPoint||g.s.lastTown:g.s.party;const seen=new Set(g.s.discovered),visited=id=>id==='haventide'||g.s.flags['visited_'+id];return `<div class="map-layout"><div class="atlas" aria-label="World map. Drag or use WASD to pan; wheel to zoom."><svg viewBox="${x} ${y} ${vw} ${vh}" aria-label="Map of the eight connected regions"><defs><pattern id="atlas-grain" width="95" height="95" patternUnits="userSpaceOnUse"><circle cx="15" cy="20" r="1.8" fill="#887458" opacity=".35"/><path d="M44 45h12M69 79h5" stroke="#8b785b" stroke-width="2" opacity=".13"/></pattern><pattern id="atlas-fog" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M0 24 24 0" stroke="#a99d86" stroke-width="2" opacity=".15"/></pattern></defs><rect x="-3200" y="-1920" width="9600" height="5760" fill="#d5c9aa"/><rect x="-3200" y="-1920" width="9600" height="5760" fill="url(#atlas-grain)"/>${REGIONS.map(r=>{const known=seen.has(r.id);const color=r.palette.ground;return `<g class="atlas-region ${known&&r.town&&visited(r.id)?'travel':''}" ${known&&r.town&&visited(r.id)?`data-action="fastTravel" data-payload="${esc(JSON.stringify({regionId:r.id}))}" role="button" tabindex="0" aria-label="Travel to ${esc(r.name)}"`:''}><rect x="${r.x+8}" y="${r.y+8}" width="${r.w-16}" height="${r.h-16}" rx="24" fill="${known?color:'#b8b09a'}" fill-opacity="${known?'.30':'.17'}" stroke="${known?'#897861':'#ada087'}" stroke-width="4" stroke-dasharray="${known?'':'9 11'}"/>${!known?`<rect x="${r.x+10}" y="${r.y+10}" width="${r.w-20}" height="${r.h-20}" fill="url(#atlas-fog)"/>`:''}<text x="${r.x+r.w/2}" y="${r.y+135}" text-anchor="middle" fill="${known?'#50474a':'#9a8c7c'}" font-size="${r.name.length>12?48:55}">${known?esc(r.name):'Uncharted'}</text><text x="${r.x+r.w/2}" y="${r.y+188}" text-anchor="middle" fill="#8b7863" font-size="24" letter-spacing="4">${known?`REGION ${r.tier}`:'◇'}</text>${known?mapRegionDetails(r,g):''}</g>`;}).join('')}<path d="M400 960H2800M1200 320V1600M2000 320V960M400 960V1600M400 1600H1200" fill="none" stroke="#a08764" stroke-width="12" stroke-linecap="round" stroke-dasharray="11 14" opacity=".52"/><circle cx="${p.x}" cy="${p.y}" r="33" fill="#be527e" stroke="#fff0cc" stroke-width="12"/><circle cx="${p.x}" cy="${p.y}" r="61" fill="none" stroke="#b8577c" stroke-width="5" opacity=".45"/></svg><div class="map-compass">N<strong>✧</strong>S</div><div class="map-legend">● Your party &nbsp; ◇ Anchor<br>▰ Settlement &nbsp; × Encounter</div><div class="map-tools">${button('−','uiMap',{factor:1/1.2},{class:'',label:'Zoom map out'})}${button('⌖','uiMap',{reset:true},{class:'',label:'Reset map'})}${button('+','uiMap',{factor:1.2},{class:'',label:'Zoom map in'})}</div></div><aside class="atlas-sidebar"><div class="eyebrow">The old roads</div><h3 style="margin-top:7px">A connected world</h3><p class="small muted">Roads join every region. Walk into the unknown, then return to a visited town from here.</p><div class="travel-list">${TOWNS.map(t=>button(`<strong>${esc(t.name)}</strong><small>${visited(t.region)?'↗ Fast travel':'Visit this town to unlock'}</small>`,'fastTravel',{regionId:t.region},{class:'travel-stop',disabled:!visited(t.region),label:`Fast travel to ${t.name}`})).join('')}</div><p class="atlas-footnote">${seen.size} / 8 regions discovered<br>${Math.round(m.zoom*100)}% magnification · drag to explore</p></aside></div>`;}
function mapRegionDetails(r,g){const features=OBJECTS.filter(o=>o.region===r.id&&['anchor','encounter','hall','chest'].includes(o.type));return features.map(o=>{const done=o.type==='chest'?g.s.chests.includes(o.id):o.type==='encounter'?g.s.cleared[o.id]:o.type==='anchor'?g.s.flags[`anchor_${r.id==='crater'?'ember':r.id}`]:false;return `<text x="${o.x}" y="${o.y+14}" text-anchor="middle" font-family="Georgia,serif" font-size="${o.type==='hall'?64:46}" fill="${done?'#749072':o.type==='encounter'?'#995b59':'#856439'}" opacity=".85">${o.type==='hall'?'▰':o.type==='encounter'?'×':o.type==='anchor'?'◇':'·'}</text>`;}).join('');}
function dialogue(g){const d=g.dialogue||{lines:[],index:0},line=d.lines[d.index]||{},speaker=line.speaker||'A moment on the road';const hero=Object.keys(HEROES).find(id=>id===String(speaker).toLowerCase()||HEROES[id].name===speaker);const portraitId=hero||(/^Iona(?:$|\s|\s·)/i.test(speaker)?'iona':null);const last=d.index>=d.lines.length-1;return `<section class="dialogue-box" role="dialog" aria-label="Conversation with ${esc(speaker)}">${portraitId?`<div class="dialogue-portrait" style="${heroStyle(portraitId)}">${portrait(portraitId,78,110)}</div>`:''}<div class="dialogue-copy"><div class="dialogue-speaker"${hero?` style="color:${HEROES[hero].color}"`:''}>${esc(speaker)}</div><p class="dialogue-text">${esc(line.text)}</p><div class="dialogue-footer"><div class="dialogue-dots">${d.lines.map((_,i)=>`<i class="${i===d.index?'active':''}"></i>`).join('')}</div><div class="actions">${last&&d.choices?.length?d.choices.map(c=>button(esc(c.label),'dialogueChoice',{id:c.id},{title:c.detail,class:'button',label:c.label,disabled:c.disabled})).join(''):button(`${last?'Onward':'Continue'} &nbsp; <kbd>Space</kbd>`,'dialogueNext',{}, {class:'button subtle',label:'Continue dialogue'})}</div></div></div></section>`;}
function serviceFrame(g,{name,mark,eyebrow,body,footer,extra=''}){return `<div class="scrim"></div><section class="service-frame" role="dialog" aria-label="${esc(name)}"><header class="service-header"><div class="service-mark">${icon(mark)}</div><div><div class="eyebrow">${esc(eyebrow)}</div><h2>${esc(name)}</h2></div>${extra}${button('×','close',{}, {class:'icon-button',label:'Leave '+name})}</header><div class="service-body">${body}</div><footer class="service-footer"><span>${esc(footer)}</span><span>${num(g.s.resources.coins)} coins · ${num(g.s.resources.ore)} ore · ${num(g.s.resources.energy)} energy</span></footer></section>`;}
function shop(g){const sellMode=g.ui.shopTab==='sell',tier=g.shop?.tier||1;const items=sellMode?g.s.inventory:values(ITEMS).filter(i=>i.tier<=tier);return serviceFrame(g,{name:g.shop?.name||'The Wayfarer’s Goods',mark:'inventory',eyebrow:'Good supplies, longer roads',footer:'Equipment requirements are shown beside each item.',extra:`<div class="shop-tabs">${button('Buy','uiShop',{tab:'buy'},{class:`filter ${!sellMode?'active':''}`})}${button('Sell','uiShop',{tab:'sell'},{class:`filter ${sellMode?'active':''}`})}</div>`,body:`<p class="merchant-quote">“A full flask, a warm coat, and something sharp. The rest you’ll find out there.”</p><div class="shop-list scroll">${items.map(i=>{const d=sellMode?ITEMS[i.id]:i,own=sellMode&&owner(g.s,i.uid);const value=sellMode?Math.max(1,Math.floor(d.price*(.45+.12*i.rank))):d.price;return `<div class="shop-row"><span class="item-symbol">${itemIcon(d.id)}</span><span class="item-copy"><strong>${esc(sellMode?itemName(i):d.name)} <span class="tiny muted">· ${d.heroes?d.heroes.map(id=>HEROES[id].name).join(' / '):'All'} · Lv ${d.level}</span></strong><small>${esc(d.desc)} ${d.slot!=='consumable'?`<span class="gold">${esc(statText(sellMode?itemStats(i):d.stats))}</span>`:''}</small></span>${button(`${own?`Equipped · ${own.name}`:`${sellMode?'Sell':'Buy'} · ${value} coins`}`,sellMode?'sell':'buy',sellMode?{uid:i.uid}:{itemId:i.id},{disabled:!!own||(!sellMode&&g.s.resources.coins<value),label:`${sellMode?'Sell':'Buy'} ${sellMode?itemName(i):d.name}`})}</div>`;}).join('')}</div>`});}
function forge(g){const discount=Math.round(settlementInfo(g.s).forgeDiscount*100);return serviceFrame(g,{name:g.shop?.name||'The Ember & Anvil',mark:'forge',eyebrow:'Give an old companion a new edge',footer:discount?`The community forge reduces your costs by ${discount}%.`:'Build a community forge to lower upgrade costs.',body:`<p class="merchant-quote">“You needn’t throw away a blade that’s carried you this far. Let’s teach it something new.”</p><div class="shop-list scroll">${g.s.inventory.filter(i=>ITEMS[i.id].slot!=='consumable').map(i=>{const d=ITEMS[i.id],cost=upgradeCost(g.s,i),own=owner(g.s,i.uid),before=itemStats(i),after=itemStats({...i,rank:i.rank+1});return `<div class="shop-row"><span class="item-symbol">${itemIcon(d.id)}</span><span class="item-copy"><strong>${esc(itemName(i))} <span class="tiny muted">${own?`· ${own.name}`:''}</span></strong><small>${Object.entries(before).map(([k,v])=>`${STAT_NAMES[k]} ${v}${cost?` → <span class="positive">${after[k]}</span>`:''}`).join(' · ')}</small>${cost?`<div style="margin-top:5px">${price(cost)}</div>`:'<small class="gold">Masterwork · maximum rank</small>'}</span>${button(cost?`Forge to +${i.rank+1}`:'Masterwork','upgradeItem',{uid:i.uid},{disabled:!affordable(g.s,cost)||(own&&own.level<i.rank+1),label:`Upgrade ${itemName(i)}`})}</div>`;}).join('')}</div>`});}
function settlement(g){const s=g.s,info=settlementInfo(s),hall=s.settlement.hall,plot=Number.isInteger(g.settlementPlot)?g.settlementPlot:-1,selected=s.settlement.plots[plot];const hallCost=buildingCost(s,-1),hallReady=info.anchorCount>=(hall===1?1:3);let content;if(plot===-1){content=`<div class="eyebrow">Seven plots. One place to belong.</div><h3 style="margin-top:7px">The commons</h3><p class="small muted" style="margin:9px 0 6px">Choose a plot to build or improve. Homes, gardens and shared work turn this harbor into a place people can stay.</p><div class="building-list scroll" style="height:226px">${s.settlement.plots.map((p,i)=>{const d=BUILDINGS[p?.type];return `<div class="building-row"><div class="building-symbol">${icon(p?.type||'hall')}</div><div class="building-copy"><h4>Plot ${i+1} · ${d?esc(d.name):'An open patch of earth'}</h4><p>${d?`Rank ${p.tier} · ${esc(d.desc)}`:'Ready for something worth making.'}</p></div>${button(d?'Manage':'Build','uiPlot',{plot:i},{label:`${d?'Manage':'Build on'} plot ${i+1}`})}</div>`;}).join('')}</div>`;}else if(selected){const d=BUILDINGS[selected.type],cost=buildingCost(s,plot),tier=selected.tier;content=`<div class="eyebrow">Plot ${plot+1} · Rank ${tier} / 3</div><h3 style="font-size:32px;margin:8px 0 12px">${esc(d.name)}</h3><p class="small muted">${esc(d.desc)}</p><div class="divider"></div>${d.production?`<div class="stock-row"><span>${icon(d.production)} Production</span><b>${d.rate*tier} ${d.production} / min</b></div><div class="stock-row"><span>Storage contribution</span><b>${d.capacity*tier*hall} ${d.production}</b></div>`:Object.entries(d.bonus||{}).map(([k,v])=>`<div class="stock-row"><span>${k==='forgeDiscount'?'Forge discount':`Party ${STAT_NAMES[k]}`}</span><b>${k==='forgeDiscount'?`${Math.round(v*tier*100)}%`:`+${v*tier}`}</b></div>`).join('')}<div class="divider"></div>${cost?`<p class="tiny muted" style="margin-bottom:9px">${tier>=hall?`A rank ${tier+1} town hall is needed first.`:`Next rank: ${d.production?`${d.rate*(tier+1)} ${d.production} per minute`:'Increased benefit for the whole party'}.`}</p>${price(cost)}<div class="actions" style="margin-top:14px">${button(`Upgrade ${esc(d.name)} to rank ${tier+1}`,'upgradeBuilding',{plot},{class:'button primary',disabled:tier>=hall||!affordable(s,cost),label:`Upgrade ${d.name}`})}</div>`:'<p class="small gold">Fully restored. A lasting piece of Haventide.</p>'}<div class="actions" style="margin-top:18px">${button('← Back to the commons','uiPlot',{plot:-1},{class:'button subtle'})}</div>`;}else{content=`<div class="eyebrow">Plot ${plot+1} · A beginning</div><h3 style="margin:7px 0 10px">What shall we build?</h3><div class="building-list scroll" style="height:285px">${values(BUILDINGS).map(d=>{const cost=buildingCost(s,plot,d.id);return `<div class="building-row"><div class="building-symbol" style="color:${d.color}">${icon(d.id)}</div><div class="building-copy"><h4>${esc(d.name)}</h4><p>${esc(d.desc)}${d.production?` ${d.rate} / min · stores ${d.capacity*hall}.`:''}</p>${price(cost)}</div>${button('Build','build',{plot,type:d.id},{disabled:!affordable(s,cost),label:`Build ${d.name} on plot ${plot+1}`})}</div>`;}).join('')}</div>`;}return serviceFrame(g,{name:'A home at Haventide',mark:'hall',eyebrow:'Build something time cannot take',footer:'Production accumulates during exploration and battles. Collect it here.',body:`<div class="settlement-layout"><aside class="settlement-summary"><div class="eyebrow">Town hall</div><div class="hall-level">${hall}<small>Rank of three</small></div>${['food','ore','energy'].map(key=>`<div class="stock-row"><span>${icon(key)}${key[0].toUpperCase()+key.slice(1)}</span><b>${Math.floor(info.stock[key])} / ${info.caps[key]}<br><small>+${info.rates[key]} / min</small></b></div>`).join('')}<div class="actions">${button('Collect production','collect',{}, {class:'button primary',disabled:!values(info.stock).some(n=>n>=1)})}${hallCost?button(`Upgrade hall · ${hall+1}`,'upgradeBuilding',{plot:-1},{disabled:!hallReady||!affordable(s,hallCost),label:'Upgrade town hall',title:costWords(hallCost)}):'<p class="tiny gold">Town hall fully restored</p>'}</div>${hallCost?`<p class="tiny muted">${hallReady?`Next rank: ${costWords(hallCost)}`:`Restore ${hall===1?'one anchor':'all three anchors'} to improve the hall.`}</p>`:''}<div class="plot-select">${s.settlement.plots.map((p,i)=>button(String(i+1),'uiPlot',{plot:i},{class:`plot-number ${plot===i?'active':''} ${p?'built':''}`,label:`Select plot ${i+1}`})).join('')}</div>${button('View the commons','uiPlot',{plot:-1},{class:'button subtle small-btn'})}</aside><div style="min-height:0">${content}</div></div>`});}
function battleHud(g){const b=g.battle,v=battleView(g);if(!b)return ribbon(g);const heroes=b.heroes||[],ready=HEROES[v.readyHero];return `${ribbon(g)}<div class="battle-heading"><div class="eyebrow">${b.encounter?.boss?'A memory that fights back':'The road pushes back'}</div><h2>${esc(b.encounter?.name||'A clash in the broken hour')}</h2></div><div class="battle-mode"><span class="eyebrow">${g.s.settings.wait?'Wait mode':'Active mode'}</span><br><span class="tiny">${g.s.settings.speed}× battle speed</span></div><div class="battle-log" aria-live="polite">${(v.log||[]).slice(-3).map((l,i,a)=>`<div class="${i===a.length-1?'last':'older'}">${esc(l)}</div>`).join('')}</div><section class="battle-panel" aria-label="Party battle status"><div class="battle-rows">${heroes.map(h=>{const meta=HEROES[h.id],t=h.stats||stats(g.s,h.id),status=values(h.status||{}).some(n=>n>0)?Object.entries(h.status).filter(([,n])=>n>0&&typeof n!=='object').map(([k])=>k).join(' · '):h.hp<=0?'Fallen':v.readyHero===h.id?'Command ready':h.atb>=100?'Ready':'Preparing';return `<div class="battle-row ${v.readyHero===h.id?'ready':''}" style="${heroStyle(h.id)}" data-hero-status="${h.id}">${button(`${portrait(h.id,25,32)}<div><strong>${esc(meta.name)}</strong><small>${esc(status)}</small></div>`,'battle',{action:'hero',id:h.id},{class:'battle-hero-label',disabled:h.hp<=0||h.atb<100,label:`Select ${meta.name} in battle`})}<div class="battle-meter"><div class="meter-label"><span>HP</span><b>${num(h.hp)} / ${num(t.maxHp)}</b></div>${meter(h.hp,t.maxHp)}</div><div class="battle-meter"><div class="meter-label"><span>MP</span><b>${num(h.mp)} / ${num(t.maxMp)}</b></div>${meter(h.mp,t.maxMp,'#79b9c9')}</div><div class="battle-meter atb"><div class="meter-label"><span>ATB</span><b>${h.hp<=0?'—':h.atb>=100?'READY':`${Math.floor(h.atb||0)}%`}</b></div>${meter(h.atb,100,'#dabb79')}</div></div>`;}).join('')}</div><div class="battle-footnote"><h3>${ready?`${esc(ready.name)}’s moment`:'Every second matters'}</h3><p>${ready?'Choose a technique, protect the party, or wait for your allies to act together.':'Active time fills for each companion. Your next opening is approaching.'}</p></div></section>`;}
function battleOverlay(g){const b=g.battle,v=battleView(g);if(v.phase==='victory'||v.phase==='defeat')return result(g,v.phase==='victory',b.reward||g.reward,true);if(v.waiting&&!v.readyHero&&v.commands.length)return `<section class="command-panel" role="dialog" aria-label="Waiting for allies"><header class="command-header"><strong>Together, soon</strong></header><p class="small muted" style="margin:8px 0">Time advances until every living ally is ready.</p>${v.commands.map(c=>button(esc(c.label),'battle',{action:'command',id:c.id},{class:'button',disabled:c.disabled})).join('')}</section>`;if(!v.readyHero||['windup','impact','recovery'].includes(v.phase))return `<div class="battle-wait">${v.phase==='filling'?'The next moment is gathering…':''}</div>`;const ready=HEROES[v.readyHero],targeting=v.view==='target',commands=targeting?v.targets:v.commands,head=targeting?'Choose a target':v.view==='skills'?'Techniques':v.view==='links'?'Together':v.view==='items'?'Field supplies':'Your next move';return `<section class="command-panel ${v.view==='main'?'command-main':''}" role="dialog" aria-label="Battle commands"><header class="command-header"><strong>${head}</strong><small style="color:${ready.color}">${ready.name}</small></header><div class="command-list scroll">${commands.map((c,i)=>button(`${v.view==='items'&&getItem(g.s,c.id)?itemIcon(getItem(g.s,c.id).id,22):icon(targeting?'arrow':v.view==='main'?c.id:v.view==='links'?'link':'tech')}<span>${esc(c.label)}${c.detail&&v.view!=='main'?`<small>${esc(c.detail)}</small>`:''}</span><span class="command-arrow">›</span>`,'battle',{action:targeting?'target':v.view==='main'?'command':'select',id:c.id},{class:'command-button',disabled:c.disabled,label:c.label,title:c.detail})).join('')||'<p class="empty">No available choices.</p>'}</div>${v.view!=='main'?button('← Back','battle',{action:'back'},{class:'command-back'}):''}</section>`;}
function result(g,win=true,reward={},inBattle=false){reward||={};const messages=reward.messages||[];return `<div class="scrim"></div><section class="result-card" role="dialog" aria-label="${win?'Battle won':'Defeat'}"><div class="eyebrow">${win?'A little more of the future is yours':'The hour can turn again'}</div><h2>${win?'A moment reclaimed':'Take another breath'}</h2>${win?`<div class="result-loot">${[['XP',reward.xp],['Coins',reward.coins],['Ore',reward.ore]].map(([label,n])=>`<div><strong>+${num(n)}</strong><small>${label}</small></div>`).join('')}</div>${reward.items?.length?`<div class="result-items">${reward.items.map(i=>{const id=typeof i==='string'?i:i.id,name=typeof i==='string'?(ITEMS[i]?.name||i):i.name||ITEMS[i.id]?.name||'Equipment';return `<span class="result-item">${ITEMS[id]?itemIcon(id,22):''}<span>${esc(name)}</span></span>`;}).join('')}</div>`:''}<div class="result-messages">${messages.map(m=>esc(m)).join('<br>')}</div>`:'<p class="small muted" style="margin:15px 0 23px">Your companions are still here. Retry this encounter with your supplies restored, or return to the last town and prepare.</p>'}<div class="actions">${win?button('Continue the journey',inBattle?'battle':'rewardContinue',inBattle?{action:'continue'}:{},{class:'button primary'}):`${button('Retry encounter',inBattle?'battle':'retry',inBattle?{action:'retry'}:{},{class:'button primary'})}${button('Return to town',inBattle?'battle':'retreat',inBattle?{action:'retreat'}:{})}`}</div></section>`;}
function ending(g){const e=g.ending||{},paragraphs=e.paragraphs||[];return `<section class="ending-screen" aria-label="Journey complete"><div class="ending-copy"><div class="eyebrow">The chronicle closes. Life goes on.</div><h1>${esc(e.title||'The Unwritten Hour')}</h1><div class="ending-ornament"></div><div class="ending-story scroll" aria-label="The companions’ homecoming" tabindex="0">${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="actions">${button('Return to Haventide','endingContinue',{}, {class:'button primary'})}${button('Keep this hour','save',{slot:'1'})}<span class="ending-scroll-hint">Scroll to read the homecoming ↓</span></div><p class="tiny muted" style="font-family:inherit;margin-top:14px">${g.s.settlement.plots.filter(Boolean).length} commons buildings · ${g.s.discovered.length} regions explored · ${Math.floor(g.s.elapsed/60)} minutes together</p></div></section>`;}
// The HUD is CSS-scaled with the stage. Measure the displayed size so portraits
// and icons keep their source detail at any stage size or device pixel ratio.
// Logical dimensions preserve framing; only backing pixels change (512px cap).
function spriteCanvas(c){
 const width=Number(c.dataset.spriteWidth),height=Number(c.dataset.spriteHeight),rect=c.getBoundingClientRect();
 if(!rect.width||!rect.height)return null;
 const density=Math.min(window.devicePixelRatio||1,512/Math.max(rect.width,rect.height));
 const pw=Math.max(1,Math.round(rect.width*density)),ph=Math.max(1,Math.round(rect.height*density));
 if(c.width!==pw)c.width=pw;if(c.height!==ph)c.height=ph;
 const ctx=c.getContext('2d');ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,pw,ph);
 ctx.setTransform(pw/width,0,0,ph/height,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';
 return {ctx,width,height};
}
function paintPortraits(g){for(const c of document.querySelectorAll('canvas[data-item-icon]')){const surface=spriteCanvas(c);if(surface)drawItemIcon(surface.ctx,c.dataset.itemIcon,0,0,surface.width);}if(g.mode==='battle'&&g.overlay==='menu'){const chapter=document.querySelector('.menu-title .chapter');if(chapter)chapter.textContent='Battle paused · review or adjust settings';for(const b of document.querySelectorAll('#overlay [data-action]'))if(['save','load','deleteSave','uiDelete','fastTravel','equip','unequip','learn','useItem','sell'].includes(b.dataset.action)){b.disabled=true;b.title='Available after this encounter.';}}for(const c of document.querySelectorAll('canvas[data-portrait]')){const surface=spriteCanvas(c);if(!surface)continue;const {ctx,width,height}=surface;if(c.dataset.portrait==='iona')drawPortrait(ctx,'iona',0,(height-width)/2,width);else if(height<75)drawPortrait(ctx,c.dataset.portrait,0,0,Math.min(width,height));else drawHero(ctx,c.dataset.portrait,'idle',width/2,height-3,Math.min(width/66,height/84),'right',g.time,{reducedMotion:!!g.s.settings.reducedMotion});}}
export function renderUI(g){setup(g);document.getElementById('game').classList.toggle('reduced-motion',!!g.s.settings.reducedMotion);const hud=document.getElementById('hud'),over=document.getElementById('overlay');const h=g.mode==='title'||g.mode==='ending'?'':g.mode==='battle'?battleHud(g):worldHud(g);let o='';if(g.mode==='title')o=title(g);else if(g.mode==='ending')o=ending(g);else if(g.overlay==='menu')o=menu(g);else if(g.overlay==='dialogue')o=dialogue(g);else if(g.overlay==='shop')o=shop(g);else if(g.overlay==='forge')o=forge(g);else if(g.overlay==='settlement')o=settlement(g);else if(g.mode==='battle')o=battleOverlay(g);else if(g.mode==='reward')o=result(g,g.reward?.win!==false,g.reward);if(h!==lastHud){reconcile(hud,h);lastHud=h;}if(o!==lastOverlay){reconcile(over,o);lastOverlay=o;}paintPortraits(g);const mini=document.getElementById('minimap');if(mini){const ctx=mini.getContext('2d');ctx.setTransform(2,0,0,2,0,0);ctx.clearRect(0,0,139,77);drawMinimap(ctx,g,0,0,139,77);}}
export function handleUIKey(g,key){const k=key.toLowerCase();if(g.mode==='title'){if(k==='enter'||k===' '){g.act(saveMeta('auto')?'continue':'newGame',{slot:'auto'});return true;}return false;}if(g.overlay==='dialogue'){if([' ','enter'].includes(k)){const d=g.dialogue;if(d.index>=d.lines.length-1&&d.choices?.length){const focused=document.activeElement;if(focused?.dataset.action==='dialogueChoice')focused.click();return true;}g.act('dialogueNext');}return true;}if(g.overlay==='menu'){if(k==='enter'&&document.activeElement?.dataset.action&&document.activeElement.closest('#overlay')&&g.ui.tab!==2){document.activeElement.click();return true;}if(k==='escape'||k==='tab'){g.act('close');return true;}if(k==='q'||k==='arrowleft'){g.ui.tab=(g.ui.tab+6)%7;g.refresh();return true;}if(k==='e'||k==='arrowright'){g.ui.tab=(g.ui.tab+1)%7;g.refresh();return true;}if(/^[1-7]$/.test(k)){g.ui.tab=Number(k)-1;g.refresh();return true;}if(g.ui.tab===0){const m=mapState(g),step=160/m.zoom;if(k==='w'||k==='arrowup')mapChange(g,{cy:m.cy-step});if(k==='s'||k==='arrowdown')mapChange(g,{cy:m.cy+step});if(k==='a')mapChange(g,{cx:m.cx-step});if(k==='d')mapChange(g,{cx:m.cx+step});if(k==='+'||k==='=')mapChange(g,{zoom:m.zoom*1.15});if(k==='-'||k==='_')mapChange(g,{zoom:m.zoom/1.15});if(k==='r'||k==='0'){g.ui.map=null;g.refresh();}}if([1,2,3].includes(g.ui.tab)){if(k==='a'||k==='d'){g.ui.hero=(g.ui.hero+(k==='a'?2:1))%3;g.refresh();}}if(g.ui.tab===2){const items=inventoryItems(g),idx=Math.max(0,items.findIndex(i=>i.uid===g.ui.item)),h=g.s.heroes[g.ui.hero];if(k==='w'||k==='arrowup'||k==='s'||k==='arrowdown'){const i=items[(idx+(k==='w'||k==='arrowup'?items.length-1:1))%items.length];if(i){g.ui.item=i.uid;g.refresh();}}if(k==='enter'){const item=items.find(i=>i.uid===g.ui.item)||items[0];if(item)g.act(ITEMS[item.id].slot==='consumable'?'useItem':'equip',{heroId:h.id,uid:item.uid});}if(k==='x')g.act('unequip',{heroId:h.id,slot:g.ui.slot||'weapon'});}return true;}if(['shop','forge','settlement'].includes(g.overlay)){if(k==='escape'||k==='tab')g.act('close');return true;}if(g.mode==='battle'){const v=battleView(g);if(k==='escape'||k==='backspace'||k==='b'){g.act('battle',{action:'back'});return true;}if(k==='enter'||k===' '){if(['victory','defeat'].includes(v.phase)){g.act('battle',{action:v.phase==='victory'?'continue':'retry'});return true;}const focused=document.activeElement;if(focused?.dataset.action==='battle'&&!focused.disabled&&!focused.classList.contains('battle-hero-label')){focused.click();return true;}document.querySelector('.command-panel button:not(:disabled)')?.click();return true;}if(['arrowdown','arrowup','w','s'].includes(k)||(v.view==='target'&&['a','d','arrowleft','arrowright'].includes(k))||/^[1-9]$/.test(k)){const buttons=[...document.querySelectorAll('.command-button:not(:disabled)')];if(buttons.length){const i=buttons.indexOf(document.activeElement);if(/^[1-9]$/.test(k))buttons[Number(k)-1]?.click();else buttons[(i+(['arrowdown','s','d','arrowright'].includes(k)?1:buttons.length-1)+buttons.length)%buttons.length].focus();}return true;}return true;}if(g.mode==='reward'&&(k==='enter'||k===' ')){g.act('rewardContinue');return true;}return false;}
